const visual = {
  prepare: function (input) {
    var labels = ['0', '20', '40', '60', '80', '100'];
    var reqs = [];
    for (var i = 0; i < labels.length; i++) {
      reqs.push({ kind: 'text', payload: labels[i] });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var labels = ['0', '20', '40', '60', '80', '100'];
    var padX = Math.max(56, W * 0.12);
    var left = padX;
    var right = W - padX;
    var axisY = H * 0.55;
    var tickLen = Math.max(6, Math.min(12, H * 0.05));
    var cmds = visualSdk.polyline([[left, axisY], [right, axisY]]);
    var xs = [];
    for (var i = 0; i < labels.length; i++) {
      var x = left + (right - left) * i / (labels.length - 1);
      xs.push(x);
      cmds = cmds.concat(visualSdk.polyline([[x, axisY - tickLen], [x, axisY + tickLen]]));
    }
    var children = [];
    children.push({ type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } });
    for (var j = 0; j < labels.length; j++) {
      children.push({
        type: 'label',
        contentId: 'c' + j,
        anchor: { x: xs[j], y: axisY + tickLen + 8 },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-axis',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'axis', commands: cmds }],
      root: { type: 'group', children: children }
    };
  }
};
